```json
{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "A frase 'Paris foi o dobro dos outros dois juntos' liga Paris ao grupo Lisboa + Roma. Se Lisboa + Roma valem 1 parte, Paris vale 2 partes e o total tem 3 partes. Isso dá Lisboa + Roma sem equação complicada. Atenção ao que se pede: Paris + Roma, não Lisboa + Roma.",
      "motivo": "Frase mais clara e o cuidado final fica correto (pedido é Paris + Roma, não 'Roma sozinha')."
    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["P, L, R", "número de passagens vendidas para Paris, Lisboa e Roma"],
        ["conjuntamente", "somando os dois destinos citados"],
        ["L/2", "a metade de L (L dividido por 2)"]
      ],
      "motivo": "Explica a notação de fração usada nos passos."
    },
    {
      "campo": "resolucao.passos[3].porque",
      "depois": "Troque R por L/2 + 2 em L + R = 26. Fica L + L/2 + 2 = 26. Passe o 2 para o outro lado: 3L/2 = 24. Então L = 16 e R = 26 − 16 = 10.",
      "motivo": "Mostra a passagem intermediária que estava pulada."
    },
    {
      "campo": "resolucao.erradas.B",
      "depois": "38 não confere: Paris sozinha vendeu 52 (o dobro de 26). Paris + Roma não pode ser menor que 52. Essa é a conta que derruba a letra.",
      "motivo": "Mais direto para o aluno que marcou B."
    },
    {
      "campo": "resolucao.quadro",
      "depois": [
        {"linha": "P + L + R = 78", "nota": "total de passagens"},
        {"linha": "P = 2(L + R)", "nota": "Paris é o dobro dos outros dois"},
        {"linha": "R = \\frac{L}{2} + 2", "nota": "Roma: metade de Lisboa mais 2"},
        {"linha": "2(L + R) + (L + R) = 78", "nota": "troque P por 2(L + R)", "destaque": "2(L + R)"},
        {"linha": "3(L + R) = 78", "nota": "junte: 2 partes + 1 parte = 3 partes"},
        {"linha": "L + R = \\frac{78}{3}", "nota": "o 3 passa dividindo", "mov": [{"termo": "3", "de": "esquerda", "para": "denominador", "vira": "3", "como": "passa dividindo"}]},
        {"linha": "L + R = 26", "nota": "78 ÷ 3 = 26"},
        {"linha": "P = 2 × 26 = 52", "nota": "Paris"},
        {"linha": "L + \\frac{L}{2} + 2 = 26", "nota": "troque R por L/2 + 2"},
        {"linha": "L + \\frac{L}{2} = 26 - 2", "nota": "o + 2 atravessa o igual e vira − 2", "mov": [{"termo": "+ 2", "de": "esquerda", "para": "direita", "vira": "− 2", "como": "atravessa o igual"}]},
        {"linha": "\\frac{3L}{2} = 24", "nota": "L + L/2 = 3L/2 e 26 − 2 = 24"},
        {"linha": "3L = 24 × 2", "nota": "o 2 passa multiplicando", "mov": [{"termo": "2", "de": "denominador", "para": "direita", "vira": "× 2", "como": "passa multiplicando"}]},
        {"linha": "L = \\frac{48}{3} = 16", "nota": "o 3 passa dividindo: Lisboa", "mov": [{"termo": "3", "de": "esquerda", "para": "denominador", "vira": "3", "como": "passa dividindo"}]},
        {"linha": "R = 26 - 16 = 10", "nota": "Roma"},
        {"linha": "P + R = 52 + 10 = 62", "nota": "o que a questão pede"}
      ],
      "motivo": "Frações em \\frac e cada passagem escrita (mov do 2, do 3, do +2), sem pular etapas."
    }
  ],
  "didatica_alertas": [],
  "didatica_ok": true
}
